//! Generates `crates/jsc-core/src/emit/unicode_data.rs`, the static Unicode
//! tables the guest runtime reads (design/runtime-memory.md §3.7). Run without
//! arguments to rewrite the file; `--check` fails when it has drifted.
//!
//! To add a table, build it in [`tables`]: the output format and the
//! `--check` comparison follow from the list.

use std::path::Path;
use std::process::ExitCode;
use std::{env, fs};

mod case;
mod norm;

/// The generated file, relative to this crate.
const OUTPUT: &str = "../../crates/jsc-core/src/emit/unicode_data.rs";

/// Decimal bytes per line of the generated file.
const BYTES_PER_LINE: usize = 24;

/// One `pub(crate) static NAME: &[u8]` of the generated file.
struct Table {
    name: &'static str,
    doc: &'static str,
    bytes: Vec<u8>,
}

/// Every table, in the order of the generated file.
fn tables() -> Result<Vec<Table>, String> {
    let mut tables = case::tables()?;
    tables.extend(norm::tables()?);
    Ok(tables)
}

/// The full text of the generated file.
fn render(tables: &[Table]) -> String {
    let mut out = format!(
        "//! Unicode data tables (design/runtime-memory.md §3.7).\n\
         //!\n\
         //! Generated by `tools/unicode-tables`; do not edit.\n\
         //! Case tables: Unicode {}.{}.{} (`char::UNICODE_VERSION`).\n\
         //! Normalization tables: Unicode {} (`icu_normalizer` {}).\n",
        char::UNICODE_VERSION.0,
        char::UNICODE_VERSION.1,
        char::UNICODE_VERSION.2,
        norm::ICU_UNICODE_VERSION,
        norm::ICU_VERSION,
    );
    for table in tables {
        out.push_str(
            &[
                "
/// ",
                table.doc,
                "
#[rustfmt::skip]
pub(crate) static ",
                table.name,
                ": &[u8] = &[
",
            ]
            .concat(),
        );
        for line in table.bytes.chunks(BYTES_PER_LINE) {
            let cells: Vec<String> = line.iter().map(u8::to_string).collect();
            out.push_str(&["    ", &cells.join(","), ",\n"].concat());
        }
        out.push_str("];\n");
    }
    out
}

fn run() -> Result<(), String> {
    let check = match env::args().nth(1).as_deref() {
        None => false,
        Some("--check") => true,
        Some(other) => return Err(format!("unknown argument `{other}`")),
    };
    let tables = tables()?;
    for table in &tables {
        println!("{}: {} bytes", table.name, table.bytes.len());
    }
    let text = render(&tables);
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join(OUTPUT);
    if check {
        let current = fs::read_to_string(&path).map_err(|e| format!("{}: {e}", path.display()))?;
        if current != text {
            return Err(format!(
                "{} is stale; run `cargo run -p unicode-tables`",
                path.display()
            ));
        }
        return Ok(());
    }
    fs::write(&path, text).map_err(|e| format!("{}: {e}", path.display()))
}

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(message) => {
            eprintln!("unicode-tables: {message}");
            ExitCode::FAILURE
        }
    }
}
